glm::vec3 normalizeDirection(glm::vec3 vec) {
    float length = glm::length(vec);
    const float epsilon = 1e-6f;
    if (length < epsilon) {
        return glm::vec3(0.0f);
    }
    return vec / length;
}

glm::vec3 normalizeDirection(glm::vec3 vec) {
    float len = sqrt(vec.x * vec.x + vec.y * vec.y + vec.z * vec.z);
    const float epsilon = 1e-6f;
    if (len < epsilon) {
        return glm::vec3(0.0f);
    }
    return vec / len;
}

